CREATE VIEW growth_feedback AS SELECT r.tenant_id,json_extract(j.value,'$.id') id,r.lesson_id,r.id submission_id,json_extract(j.value,'$.student_id') student_id,json_extract(j.value,'$.seq') seq,json_extract(j.value,'$.doc_json') doc_json,json_extract(j.value,'$.status') status,json_extract(j.value,'$.confirmed_at') confirmed_at,json_extract(j.value,'$.created_at') created_at,json_extract(j.value,'$.created_by') created_by,json_extract(j.value,'$.updated_at') updated_at,json_extract(j.value,'$.updated_by') updated_by,json_extract(j.value,'$.version') version,json_extract(j.value,'$.deleted_at') deleted_at FROM lesson_submissions r,json_each(r.personal_json) j UNION ALL SELECT r.tenant_id,json_extract(j.value,'$.id') id,r.lesson_id,NULL submission_id,json_extract(j.value,'$.student_id') student_id,json_extract(j.value,'$.seq') seq,json_extract(j.value,'$.doc_json') doc_json,json_extract(j.value,'$.status') status,json_extract(j.value,'$.confirmed_at') confirmed_at,json_extract(j.value,'$.created_at') created_at,json_extract(j.value,'$.created_by') created_by,json_extract(j.value,'$.updated_at') updated_at,json_extract(j.value,'$.updated_by') updated_by,json_extract(j.value,'$.version') version,json_extract(j.value,'$.deleted_at') deleted_at FROM lesson_comments r,json_each(r.feedback_versions_json) j;
